pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC1155Probe {
    function balanceOf(address, uint256) external view returns (uint256);
    function balanceOfBatch(address[] calldata, uint256[] calldata) external view returns (uint256[] memory);
    function setApprovalForAll(address, bool) external;
    function isApprovedForAll(address, address) external view returns (bool);
    function safeTransferFrom(address, address, uint256, uint256, bytes calldata) external;
    function safeBatchTransferFrom(address, address, uint256[] calldata, uint256[] calldata, bytes calldata) external;
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(bytes4 sel) public {
        // ERC1155 interface id derived at runtime from its seven function selectors (EIP-165)
        bytes4 erc1155Id =
            IERC1155Probe.balanceOf.selector ^
            IERC1155Probe.balanceOfBatch.selector ^
            IERC1155Probe.setApprovalForAll.selector ^
            IERC1155Probe.isApprovedForAll.selector ^
            IERC1155Probe.safeTransferFrom.selector ^
            IERC1155Probe.safeBatchTransferFrom.selector ^
            IERC165.supportsInterface.selector;

        // exclude the other two advertised ids so the rule "true iff sel == erc1155Id"
        // applies to every admissible input
        vm.assume(sel != type(IERC1155MetadataURI).interfaceId);
        vm.assume(sel != type(IERC165).interfaceId);

        bool advertised = c.supportsInterface(sel);
        assertTrue(advertised == (sel == erc1155Id));
    }
}

