pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 sel) public {
        // Canonical IERC1155 interface id, derived at runtime purely from c's own
        // public/external IERC1155 function selectors (balanceOf, balanceOfBatch,
        // setApprovalForAll, isApprovedForAll, safeTransferFrom, safeBatchTransferFrom).
        bytes4 ierc1155Id = c.balanceOf.selector ^
            c.balanceOfBatch.selector ^
            c.setApprovalForAll.selector ^
            c.isApprovedForAll.selector ^
            c.safeTransferFrom.selector ^
            c.safeBatchTransferFrom.selector;

        // General rule: any interface the contract claims to support implies it
        // supports the canonical IERC1155 interface id.
        bool ok = true;
        try c.supportsInterface(sel) returns (bool claimed) {
            if (claimed) {
                try c.supportsInterface(ierc1155Id) returns (bool supported1155) {
                    ok = supported1155;
                } catch {
                    ok = false;
                }
            }
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

