        bool isMetadataURI = interfaceId == type(IERC1155MetadataURILike).interfaceId;
        bool is1155 = interfaceId == type(IERC1155Like).interfaceId;
        bool is165 = interfaceId == type(IERC165Like).interfaceId;
        bool expected = isMetadataURI || is1155 || is165;
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool supported) {
            ok = supported == expected;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

