// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(bytes4 probedId) public {
        // General rule: for EVERY probed interface id, the contract must recognize the
        // full ERC-1155 interface family -- i.e. it accepts the probed id OR it accepts
        // the IERC1155MetadataURI interface id (an IERC1155MetadataURI contract must
        // always report true for the metadata selector). The mutant removed the
        // metadata check, so c.supportsInterface(metadata id) is false, and for any
        // probedId that is not one of the remaining ids the disjunction fails.
        bytes4 metadataId = type(IERC1155MetadataURI).interfaceId;
        bool probed = c.supportsInterface(probedId);
        bool metadata = c.supportsInterface(metadataId);
        assertTrue(probed || metadata);
    }
}

