pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC165Local {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IERC1155Local {
    function balanceOf(address account, uint256 id) external view returns (uint256);
}

interface IERC1155MetadataURILocal {
    function uri(uint256 id) external view returns (string memory);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(uint8 which) public {
        // Admissible domain: the interfaceId is one of the three selectors the contract must advertise.
        bytes4 id;
        if (which == 0) {
            id = type(IERC165Local).interfaceId;
        } else if (which == 1) {
            id = type(IERC1155Local).interfaceId;
        } else {
            id = type(IERC1155MetadataURILocal).interfaceId;
        }
        assertTrue(c.supportsInterface(id));
    }
}

