pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(uint96 tokenId, address actor) public {
        vm.assume(actor != address(0));

        // Mint one unit of token `tokenId` to `actor` so its stored balance is 1.
        vm.startPrank(address(this));
        c.mint(actor, tokenId, 1, bytes(""));
        vm.stopPrank();

        // General rule: balanceOf must report the actual stored balance of the
        // account for the id (here, exactly 1 after minting a single unit).
        assertTrue(c.balanceOf(actor, tokenId) == 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Neuron} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Neuron nrn;

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address buyer, uint256 tokenId, uint256 quantity, uint16 dailyAllowance) public {
        vm.assume(buyer != address(0) && buyer != address(c));
        dailyAllowance = uint16(bound(dailyAllowance, 1, type(uint16).max));
        quantity = bound(quantity, 1, dailyAllowance);

        // admin is address(this): create one non-finite item with price 0
        c.createGameItem("", "", false, true, 0, 0, dailyAllowance);
        tokenId = bound(tokenId, 0, 0); // exactly one item exists

        // wire up Neuron and roles so purchases succeed
        nrn = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(nrn));
        c.addSpender(address(c)); // C needs SPENDER_ROLE to approve spending

        // buyer purchases quantity of the token (price 0, so no NRN needed)
        vm.prank(buyer);
        c.mint(tokenId, quantity);

        // Rule: after minting quantity units to buyer, the public balance getter
        // must report those units (nonzero). The buggy contract always returns 0.
        assertTrue(c.balanceOf(buyer, tokenId) == quantity, "balanceOf must reflect minted balance");
    }
}
